const regionsOf = (printed) => [...new Set(printed.flatMap((a) => MAPPING[a] || []))];
export const PACKS = Object.freeze(PACKS_RAW.map((p) => {
  const all = p.emotions.map((e) => regionsOf(e.printed));
  return Object.freeze({ id: p.id, name: p.name, summary: p.summary, emotions: Object.freeze(p.emotions.map((e, k) => {
    const src = SOURCES.find((s) => s.key === e.source.key), year = Number((src.cite.match(/\((\d{4})\)/) || [])[1]);
    return Object.freeze({ id: e.id, name: e.name, family: e.family, printedName: e.printedName, printed: Object.freeze(e.printed.slice()),
      regions: Object.freeze(all[k]), shared: Object.freeze(all[k].filter((r) => all.some((o, q) => q !== k && o.includes(r)))),
      source: Object.freeze({ key: e.source.key, short: src.short, cite: src.cite, year, n: e.source.n, design: e.source.design, doi: src.doi }),
      measured: 'the areas printed by ' + src.short + ' (' + e.source.design + ', ' + e.source.n + '), and the wiring and couplings of 207 HCP adults (ENIGMA)',
      ours: 'their mapping onto the regions, the timing and the crossing rule of the impulses' }); })) });
}));

// printed areas with no region here, in order of first appearance
export const UNMAPPED = Object.freeze([...new Set(PACKS.flatMap((p) => p.emotions.flatMap((e) => e.printed)).filter((a) => !(MAPPING[a] || []).length))]);

// the honest finding over every emotion (the four affect summaries left out): regions serving two or more emotion families
export const SHARED = (() => { const by = {};
  PACKS.filter((p) => !p.summary).forEach((p) => p.emotions.forEach((e) => e.regions.forEach((r) => { (by[r] = by[r] || new Set()).add(e.family); })));
  const mapped = Object.keys(by), shared = mapped.filter((r) => by[r].size >= 2);
  return Object.freeze({ mapped: mapped.length, shared: shared.length, single: mapped.length - shared.length, regions: Object.freeze(shared),
    families: Object.freeze(Object.fromEntries(mapped.map((r) => [r, Object.freeze([...by[r]])]))) }); })();

// Positions in mm (MNI): the 82 HCP regions take their REAL centroids from human-brain-anatomy.js (fsaverage5 surface, ENIGMA) -> null here;
//   the deep parts take a peak printed in a source read (POS3D_SOURCE), or OUR placement where none was read (said so)
export const POS3D_SOURCE = Object.freeze({ VTA_L: 'Shih et al. 2022 Table 3, left VTA (passionate love)', VTA_R: 'Shih et al. 2022 Table 3, right VTA (passionate love)',
  SN_L: 'Shih et al. 2022 Table 2, left substantia nigra (maternal love)', SN_R: 'our placement: the mirror of the left substantia nigra', PAG: 'Lindquist et al. 2012 Table 1, PAG (sadness experience)',
  Hypothal: 'our placement: no hypothalamus coordinate was read', Cerebellum: 'van Elk et al. 2019 (Hum. Brain Mapp., PMC6766853) Table 4, left cerebellum peak' });
const DEEP_MNI = { VTA_L: [-2, -14, -10], VTA_R: [2, -22, -16], SN_L: [-8, -24, -14], SN_R: [8, -24, -14], PAG: [0, -38, -10], Hypothal: [0, -6, -10], Cerebellum: [-32, -66, -32] };
export const POS3D = Object.freeze(REGIONS.map((r, a) => (a < COUNTS.hcpRegions ? null : Object.freeze(DEEP_MNI[r.id].slice()))));

// the selection used by TAM and the page: a pack, one emotion of it, and a second emotion of the same pack to compare (0 none)
export function selectEmotion(P = {}) {
  const r = (v, a, b) => { const x = Math.round(Number(v)); return Number.isFinite(x) ? Math.max(a, Math.min(b, x)) : a; };
  const pk = r(P.packWiring, 0, PACKS.length - 1), pack = PACKS[pk];
  const ek = r(P.emotionWiring, 0, pack.emotions.length - 1), ck = r(P.compareWiring, 0, pack.emotions.length);
  return { pk, ek, ck, pack, emotion: pack.emotions[ek], other: ck && ck - 1 !== ek ? pack.emotions[ck - 1] : null };
}

