/** the parcels (indices into REGIONS_400) that light for a set of 82-region ids: cortical parcels whose majority region is one of them (OUR rule), the subcortical by name */
export function parcelsOf(regionIds) { const want = new Set(regionIds); return REGIONS_400.map((r, k) => ((k < 400 ? want.has(DK_OF_400[k]) : want.has(r.id)) ? k : -1)).filter((k) => k >= 0); }
/** the 82-region ids of a list that no parcel represents at this resolution */
export function lostAt400(regionIds) { const have = new Set([...DK_OF_400, ...L400.slice(400)]); return regionIds.filter((r) => !have.has(r) && REGIONS.findIndex((x) => x.id === r) < COUNTS.hcpRegions); }

